select *
from Tblmi_mfa

    usr_id = #{usr_id}
	and phone = #{phone}
	and expired_at  >  #{expired_at}
	and use_yn = #{use_yn}

		AND code = #{code}

mapper.insert:
insert into Tblmi_mfa (
	usr_id
    , phone
	, code
	, expired_at
	, count
	, use_yn
	, reg_id
	, upd_id
) values (
	#{usr_id}
	, #{phone}
	, #{code}
	, #{expired_at}
	, #{count}
	, #{use_yn}
	, #{reg_id}
	, #{upd_id}
)

mapper.update:
update Tblmi_mfa set
    use_yn = #{use_yn}

	usr_id = #{usr_id}
	and phone = #{phone}
	and code = #{code}
